/* Define a function pointer type for a callback that takes an int and returns void */
typedef void (*Callback)(int);

/* Function that accepts a callback and an integer */
void execute_callback(Callback cb, int value) {
    cb(value);
}

/* An advanced callback function that captures context via static variable */
void print_with_prefix(int value) {
    static const char *prefix = "Value: ";
    printf("%s%d\n", prefix, value);
}

int main() {
    Callback cb = print_with_prefix;  // Assign function pointer
    execute_callback(cb, 42);         // Invoke callback dynamically
    return 0;
}
